CategoryTheory.Adjunction.homEquiv_counit.{v₁, v₂, u₁, u₂} {C : Type u₁} [Category.{v₁, u₁} C] {D : Type u₂}
  [Category.{v₂, u₂} D] {F : C ⥤ D} {G : D ⥤ C} (adj : F ⊣ G) (X : C) (Y : D) (g : X ⟶ G.obj Y) :
  (adj.homEquiv X Y).symm g = F.map g ≫ adj.counit.app Y
CategoryTheory.Adjunction.homEquiv_unit.{v₁, v₂, u₁, u₂} {C : Type u₁} [Category.{v₁, u₁} C] {D : Type u₂}
  [Category.{v₂, u₂} D] {F : C ⥤ D} {G : D ⥤ C} (adj : F ⊣ G) (X : C) (Y : D) (f : F.obj X ⟶ Y) :
  (adj.homEquiv X Y) f = adj.unit.app X ≫ G.map f
theorem CategoryTheory.Adjunction.homEquiv_counit.{v₁, v₂, u₁, u₂} : ∀ {C : Type u₁} [inst : Category.{v₁, u₁} C]
  {D : Type u₂} [inst_1 : Category.{v₂, u₂} D] {F : C ⥤ D} {G : D ⥤ C} (adj : F ⊣ G) (X : C) (Y : D) (g : X ⟶ G.obj Y),
  (adj.homEquiv X Y).symm g = F.map g ≫ adj.counit.app Y :=
@Adjunction.homEquiv_symm_apply
